import React, { useState, useEffect } from "react";
import { v4 as uuidv4 } from "uuid";
import { Layout, ConfigProvider } from "antd";
import axios from "axios";
import { CKStatusType, StatusContext } from "./contexts/StatusContext";
import {
  CKWSType,
  CKWSContextType,
  CKWSContext,
} from "./contexts/WebSocketConnectionContext";
import Messages from "./components/Messages";
import MySidebar from "./components/Sidebar";
import DeveloperAccess from "./components/MyAnnotation";
import ModelSelector from "./components/MyModelSelector";

const { Header, Content, Footer, Sider } = Layout;

const App: React.FC = () => {
  const [collapsed, setCollapsed] = useState(false);
  const [CKStatus, setCKStatus] = useState<CKStatusType>({
    current_model: "cognitiveKernel",
    activated_websites: [],
    activated_functions_personalized_model: false,
    activated_functions_self_improving: false,
    activated_functions_online_annotation: false,
    uploaded_files: [],
    messages: [],
    session_id: uuidv4(),
    history_id: uuidv4(),
    username: "",
    currentMode: "normal",
  });
  // localStorage.setItem("username", "NA");
  const [CKWSConnection, setCKWSConnection] = useState<CKWSType>({
    CKWSConnection: null,
  });
  const [historyMessages, setHistoryMessages] = useState([]);
  const [canSave, setCanSave] = useState(false);

  const fetchHistory = async (model_name: string) => {
    if (CKStatus.username === "") {
      setHistoryMessages([]);
    } else {
      let data_for_retrieval = {
        model_name: model_name,
        username: CKStatus.username,
      };
      const response = await axios.post(
        "/api/retrieve_history",
        data_for_retrieval
      );
      setHistoryMessages(response.data.data);
    }
  };

  useEffect(() => {
    fetchHistory(CKStatus.current_model);
  }, [CKStatus.username, CKStatus.current_model]);

  const SaveMessage = async () => {
    let data_for_saving = {
      username: localStorage.getItem("username"),
      session_id: CKStatus.session_id,
      model_name: CKStatus.current_model,
      messages: CKStatus.messages,
      updated_time: new Date().toISOString(),
    };
    try {
      const response = await axios.post(
        "/api/save_message_to_db",
        data_for_saving
      );
    } catch (error) {
      console.error("Error saving message", error);
    }
  };

  useEffect(() => {
    if (canSave) {
      SaveMessage();
      setCanSave(false);
    }
  }, [canSave]);

  useEffect(() => {
    fetchHistory(CKStatus.current_model);
    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
    const host = window.location.host;
    const wsUrl = `${protocol}//${host}/ws/setup_ws`;
    const my_websocket = new WebSocket(wsUrl);

    my_websocket.onopen = function (event) {
      console.log("WebSocket is open now.");
    };

    my_websocket.onmessage = function (event) {
      const data = event.data;
      // console.log("Received data from server:", data);

      if (data === "[save_message]") {
        console.log("Received [save_message] from server.");
        setCanSave(true);
        setCKStatus((prevStatus) => ({
          ...prevStatus,
          currentMode: "normal",
        }));
      } else if (data === "[task_cancelled]") {
        console.log("Received [task_cancelled] from server.");
        setCKStatus((prevStatus) => ({
          ...prevStatus,
          currentMode: "stopped",
        }));
      } else {
        try {
          const json = JSON.parse(data);
          setCKStatus((prevStatus) => {
            const newMessages = prevStatus.messages.slice();
            newMessages[newMessages.length - 1].message = json;
            return { ...prevStatus, messages: newMessages };
          });
        } catch (e) {
          console.error("Error parsing JSON:", e);
        }
      }
    };

    my_websocket.onerror = function (event) {
      console.error("WebSocket error:", event);
    };

    my_websocket.onclose = function (event) {
      console.log("WebSocket is closed now.");
    };
    setCKWSConnection({ CKWSConnection: my_websocket });
    return () => {
      my_websocket.close();
      console.log("WebSocket is closed now.");
    };
  }, []);

  return (
    <Layout style={{ minHeight: "100vh" }}>
      <Sider
        width={250}
        theme="light"
        collapsed={collapsed}
        onCollapse={(value) => {
          setCollapsed(value);
        }}
      >
        <StatusContext.Provider value={{ CKStatus, setCKStatus }}>
          <CKWSContext.Provider value={{ CKWSConnection, setCKWSConnection }}>
            <MySidebar
              historyMessages={historyMessages}
              fetchHistory={fetchHistory}
            />
          </CKWSContext.Provider>
        </StatusContext.Provider>
      </Sider>
      <Layout style={{ position: "relative" }}>
        <div style={{ position: "absolute", top: 40, left: 40 }}>
          <StatusContext.Provider value={{ CKStatus, setCKStatus }}>
            <ModelSelector fetchHistory={fetchHistory} />{" "}
          </StatusContext.Provider>
        </div>
        <Content
          style={{
            margin: "0 20%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            height: "100%",
          }}
        >
          <StatusContext.Provider value={{ CKStatus, setCKStatus }}>
            <CKWSContext.Provider value={{ CKWSConnection, setCKWSConnection }}>
              <div style={{ marginTop: "auto" }}>
                {" "}
                <Messages />
              </div>
            </CKWSContext.Provider>
          </StatusContext.Provider>
        </Content>
        <ConfigProvider
          theme={{
            token: {
              colorText: "rgba(0, 0, 0, 0.5)",
              fontSize: 10,
            },
          }}
        >
          <Footer
            style={{
              textAlign: "center",
              minHeight: "8vh",
            }}
          >
            Cognitive Kernel ©{new Date().getFullYear()} Created by Tencent AI
            Lab
          </Footer>
        </ConfigProvider>
      </Layout>

      <StatusContext.Provider value={{ CKStatus, setCKStatus }}>
        <DeveloperAccess />
      </StatusContext.Provider>
    </Layout>
  );
};

export default App;

import { useContext } from "react";
import type { UploadProps } from "antd";
import { message, Upload, Button } from "antd";
import { StatusContext } from "../contexts/StatusContext";
import { UploadOutlined } from "@ant-design/icons";

function FileUploader() {
  const context = useContext(StatusContext);

  if (!context) {
    return <div>Context not available.</div>;
  }

  const { CKStatus, setCKStatus } = context;

  const props: UploadProps = {
    name: "file",
    multiple: true,
    customRequest(options) {
      const { file, onSuccess = () => {}, onError = () => {} } = options;

      const formData = new FormData();
      formData.append("file", file);

      formData.append("ckStatus", JSON.stringify(CKStatus));

      fetch("/api/upload", {
        method: "POST",
        body: formData,
      })
        .then((response) => response.json())
        .then((result) => {
          console.log("Upload success:", result);
          onSuccess(result);
        })
        .catch((error) => {
          console.error("Upload error:", error);
          onError(error);
        });
    },
    onChange(info) {
      const { status } = info.file;
      if (status !== "uploading") {
        console.log(info.file, info.fileList);
      }
      if (status === "done") {
        message.success(`${info.file.name} file uploaded successfully.`);
        setCKStatus((prevStatus) => ({
          ...prevStatus,
          uploaded_files: [...prevStatus.uploaded_files, info.file.name],
        }));
      } else if (status === "error") {
        message.error(`${info.file.name} file upload failed.`);
      }
    },
    onDrop(e) {
      console.log("Dropped files", e.dataTransfer.files);
      const droppedFiles = Array.from(e.dataTransfer.files);
      const fileNames = droppedFiles.map((file) => file.name);
      setCKStatus((prevStatus) => ({
        ...prevStatus,
        uploaded_files: [...prevStatus.uploaded_files, ...fileNames],
      }));
    },
  };

  return (
    <Upload {...props}>
      <Button icon={<UploadOutlined />}></Button>
    </Upload>
  );
}

export default FileUploader;

import { List, Typography } from "antd";
import { useContext, useState } from "react";
import { StatusContext } from "../contexts/StatusContext";
import { CopyOutlined, DeleteOutlined } from "@ant-design/icons";
import moment from "moment";
import axios from "axios";

type HistoryMessage = {
  id: number;
  session_id: string;
  initial_message: string;
  updated_time: string;
};

const renderGroup = (
  messages: HistoryMessage[],
  title: string,
  fetchHistory: (model_name: string) => void
) => {
  const context = useContext(StatusContext);

  if (!context) {
    return <div>Context not available.</div>;
  }

  const { CKStatus, setCKStatus } = context;
  const [hoveredItemId, setHoveredItemId] = useState<number>(0);

  const handleClick = async (PrimarySessionId: number, SessionId: string) => {
    const response = await axios.post("/api/retrieve_message_session_by_id", {
      session_id: PrimarySessionId,
    });
    let selected_message = JSON.parse(response.data.data["messages"]);
    console.groupCollapsed(selected_message);
    setCKStatus((prevStatus) => ({
      ...prevStatus,
      messages: selected_message,
      session_id: SessionId,
    }));
  };

  const copyToClipboardFallback = (text: string) => {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    try {
      const successful = document.execCommand("copy");
      console.log(
        "Fallback: Copying text command was " +
          (successful ? "successful" : "unsuccessful")
      );
    } catch (err) {
      console.error("Fallback: Oops, unable to copy", err);
    }
    document.body.removeChild(textArea);
  };

  if (messages.length === 0) {
    return null;
  }

  const handleArchive = async (PrimarySessionId: number) => {
    const response = await axios.post("/api/archive_message_session_by_id", {
      session_id: PrimarySessionId,
    });
    if (response.data.status === "success") {
      fetchHistory(CKStatus.current_model);
    }
  };

  return (
    <List
      header={<div>{title}</div>}
      dataSource={messages}
      renderItem={(item) => (
        <List.Item
          onClick={() => handleClick(item.id, item.session_id)}
          onMouseEnter={() => setHoveredItemId(item.id)}
          onMouseLeave={() => setHoveredItemId(0)}
          actions={
            hoveredItemId === item.id
              ? [
                  <CopyOutlined
                    onClick={(e) => {
                      e.stopPropagation();
                      copyToClipboardFallback(item.initial_message);
                    }}
                    style={{
                      color: "darkgray",
                      fontSize: "15px",
                      marginTop: "1px",
                    }}
                  />,
                  <DeleteOutlined
                    onClick={(e) => {
                      e.stopPropagation();
                      handleArchive(item.id);
                    }}
                    style={{
                      color: "darkgray",
                      fontSize: "15px",
                      marginTop: "1px",
                    }}
                  />,
                ]
              : []
          }
          style={{
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <Typography.Text ellipsis={{ tooltip: item.initial_message }}>
            {item.initial_message}
          </Typography.Text>
        </List.Item>
      )}
    />
  );
};

const HistoryList = ({
  historyMessages,
  fetchHistory,
}: {
  historyMessages: HistoryMessage[];
  fetchHistory: (model_name: string) => void;
}) => {
  const context = useContext(StatusContext);

  if (!context) {
    return <div>Context not available.</div>;
  }

  const { CKStatus, setCKStatus } = context;
  const groupMessagesByDate = (messages: HistoryMessage[]) => {
    const groups: {
      today: HistoryMessage[];
      yesterday: HistoryMessage[];
      lastWeek: HistoryMessage[];
      older: HistoryMessage[];
    } = {
      today: [],
      yesterday: [],
      lastWeek: [],
      older: [],
    };

    messages.forEach((message) => {
      const messageDate = moment(message.updated_time);
      if (messageDate.isSame(moment(), "day")) {
        groups.today.push(message);
      } else if (messageDate.isSame(moment().subtract(1, "days"), "day")) {
        groups.yesterday.push(message);
      } else if (messageDate.isAfter(moment().subtract(7, "days"))) {
        groups.lastWeek.push(message);
      } else {
        groups.older.push(message);
      }
    });

    return groups;
  };
  const groupedMessages = groupMessagesByDate(historyMessages);

  return (
    <StatusContext.Provider value={{ CKStatus, setCKStatus }}>
      <div
        style={{
          height: "70vh",
          width: "100%",
          display: "flex",
          flexDirection: "column",
          overflow: "auto",
        }}
      >
        {renderGroup(groupedMessages.today, "Today", fetchHistory)}
        {renderGroup(groupedMessages.yesterday, "Yesterday", fetchHistory)}
        {renderGroup(groupedMessages.lastWeek, "Last 7 Days", fetchHistory)}
        {renderGroup(groupedMessages.older, "Older", fetchHistory)}
      </div>
    </StatusContext.Provider>
  );
};

export default HistoryList;

import React, { useEffect, useRef, useState, useContext } from "react";
import { v4 as uuidv4 } from "uuid";
import { List, Input, ConfigProvider } from "antd";
import { MyMessageType, StatusContext } from "../contexts/StatusContext";
import { CKStatusType } from "../contexts/StatusContext";
