import React, { useState, useEffect } from "react";
import MyCodeBlock from "./MyCodeBlock";

interface MessagePart {
  type: "text" | "code";
  language: string;
  content: string;
}

function parseMessage(message: string): MessagePart[] {
  const regex = /```/g;
  let parts: MessagePart[] = [];
  let lastIndex = 0;
  let isCodeBlock = false;
  let codeLanguage = "";
  let codeLanguageLength = 0;

  message.replace(regex, (match, index) => {
    if (isCodeBlock) {
      parts.push({
        type: "code",
        language: codeLanguage,
        content: message.slice(lastIndex + codeLanguageLength + 1, index),
      });
      isCodeBlock = false;
      codeLanguage = "";
    } else {
      parts.push({
        type: "text",
        language: "",
        content: message.slice(lastIndex, index),
      });
      isCodeBlock = true;

      const languageIdentifier = message
        .slice(index + match.length)
        .match(/^[^\n]+/);
      codeLanguage = languageIdentifier
        ? languageIdentifier[0].trim()
        : "unknown";
      codeLanguageLength = languageIdentifier
        ? languageIdentifier[0].length
        : 0;
    }
    lastIndex = index + match.length;
    return match;
  });

  if (lastIndex < message.length) {
    if (isCodeBlock) {
      parts.push({
        type: "code",
        language: codeLanguage,
        content: message.slice(lastIndex),
      });
    } else {
      parts.push({
        type: "text",
        language: "",
        content: message.slice(lastIndex),
      });
    }
  }

  return parts;
}

interface RenderSingleMessageContentProps {
  messageContent: string;
}
const RenderSingleMessageContent: React.FC<RenderSingleMessageContentProps> = ({
  messageContent,
}) => {
  const messageParts = parseMessage(messageContent);
  return (
    <>
      {messageParts.map((part, partIndex) =>
        part.type === "code" ? (
          <MyCodeBlock
            key={partIndex}
            language={part.language}
            code={part.content}
          />
        ) : (
          <span key={partIndex}>{part.content}</span>
        )
      )}
    </>
  );
};

export default RenderSingleMessageContent;

import React, { useState, useEffect } from "react";
import { Image } from "antd";
import MyAnnotator from "./MyAnnotator";
import { StatusContext } from "../contexts/StatusContext";

interface RenderSingleMessageContentProps {
  messageContent: string;
  currentMessageId: string;
  annotationActivated: boolean;
}

const fetchScreenshotWithBrowserID = async (
  browserId: string,
  pageId: string,
  currentRound: string
) => {
  try {
    const response = await fetch("/web/loadScreenshot", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        browserId: browserId,
        pageId: pageId,
        currentRound: currentRound,
      }),
    });

    if (!response.ok) {
      throw new Error("Network response was not ok");
    }

    const blob = await response.blob();
    return URL.createObjectURL(blob);
  } catch (error) {
    console.error("Failed to fetch screenshot:", error);
    throw error;
  }
};

const RenderSingleMessageContentWeb: React.FC<
  RenderSingleMessageContentProps
> = ({ messageContent, currentMessageId, annotationActivated }) => {
  const [imageSrcs, setImageSrcs] = useState<string[]>([]);

  const steps = messageContent.split(/\[WEB\]/).slice(1);

  useEffect(() => {
    const newImageSrcs = steps.map(async (step) => {
      const webPrefixPattern = /^\[([^\]]+)\] \[([^\]]+)\] \[([^\]]+)\] (.*)$/;
      const match = step.trim().match(webPrefixPattern);
      if (match && !match[4].trim().startsWith("stop")) {
        const [, browserId, pageId, currentRound] = match;
        try {
          const src = await fetchScreenshotWithBrowserID(
            browserId,
            pageId,
            currentRound
          );
          return src;
        } catch (error) {
          console.error("Failed to fetch screenshot:", error);
          return "";
        }
      } else {
        return "";
      }
    });

    Promise.all(newImageSrcs).then(setImageSrcs);
  }, [messageContent]);

  return (
    <>
      {steps.map((step, index) => {
        const webPrefixPattern =
          /^\[([^\]]+)\] \[([^\]]+)\] \[([^\]]+)\] (.*)$/;
        const match = step.trim().match(webPrefixPattern);
        if (match) {
          const [, browserID, pageID, currentRound, content] = match;
          const title = `Step ${index + 1}: ${content}`;
          const imageSrc = imageSrcs[index];

          let annotation_message_id =
            currentMessageId + "@@" + "web" + "@@" + index.toString();

          return (
            <>
              <div
                key={index}
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                }}
              >
                <h3 style={{ margin: 0 }}>{title}</h3>{" "}
                {annotationActivated && index > 0 && (
                  <div>
                    <MyAnnotator messageId={annotation_message_id} />
                  </div>
                )}
              </div>
              {!content.trim().startsWith("stop") && imageSrc && (
                <Image
                  src={imageSrc}
                  alt={`Screenshot ${currentRound}`}
                  style={{ width: "100%" }}
                />
              )}
            </>
          );
        }
        return null;
      })}
    </>
  );
};

export default RenderSingleMessageContentWeb;

